actions.script:
notificationList = []
notificationListCount = 0
notificationListPageIndex = pageIndex || 0
notificationListPageSize = pageSize || 20
notificationListPageMaxIndex = 0
unreadCounts = {NinNotifications: 0, NinUpdates: 0}
approvalCount = 0
reasonCounts = {}
appCounts = {}
const userId = ec.user.userId
if (!userId) return

const topics = new Map()
for (const row of Array.from(ec.entity.find('moqui.security.user.NotificationTopic').useCache(true).disableAuthz().list()))
    topics.set(row.topic, row)
const inboxOf = (topic) => {
    const row = topics.get(topic)
    if (!row || row.approveServiceName) return 'NinNotifications'
    return row.inboxEnumId || 'NinNotifications'
}
const updateTopics = Array.from(topics.keys()).filter((topic) => inboxOf(topic) === 'NinUpdates')
const approvalTopics = Array.from(topics.values()).filter((row) => row.approveServiceName).map((row) => row.topic)
const cf = ec.entity.conditionFactory
// the inbox as a condition on the topic: Updates are the topics that name it, Notifications every other one
const inboxCondition = (inbox) => {
    if (inbox === 'NinUpdates') return updateTopics.length ? cf.makeCondition('topic', 'in', updateTopics) : cf.makeCondition('topic', 'equals', '_NA_')
    return updateTopics.length ? cf.makeCondition([cf.makeCondition('topic', 'not-in', updateTopics),
            cf.makeCondition('topic', 'equals', null)], 'or') : null
}
const mine = () => ec.entity.find('moqui.security.user.NotificationMessageByUser').condition('userId', userId).disableAuthz()
const unread = () => mine().condition('viewedDate', null)

unreadCounts.NinNotifications = unread().condition(inboxCondition('NinNotifications')).count()
unreadCounts.NinUpdates = unread().condition(inboxCondition('NinUpdates')).count()
approvalCount = approvalTopics.length ? unread().condition('topic', 'in', approvalTopics).count() : 0

const inbox = inboxEnumId === 'all' ? null : (inboxEnumId || 'NinNotifications')
if (inbox) {
    for (const row of Array.from(unread().condition(inboxCondition(inbox)).selectField('reasonEnumId,appName').list())) {
        const reason = row.reasonEnumId || ''
        const app = row.appName || ''
        reasonCounts[reason] = (reasonCounts[reason] || 0) + 1
        appCounts[app] = (appCounts[app] || 0) + 1
    }
}

if (approvals && !approvalTopics.length) return
let find = mine()
if (inbox) find = find.condition(inboxCondition(inbox))
if (approvals) find = find.condition('topic', 'in', approvalTopics).condition('viewedDate', null)
if (reasonEnumId) find = find.condition('reasonEnumId', reasonEnumId)
if (appName) find = find.condition('appName', appName)
if (topic) find = find.condition('topic', topic)
if (viewed === 'N') find = find.condition('viewedDate', null)
else if (viewed === 'Y') find = find.condition('viewedDate', 'not-equals', null)
if (fromDate) find = find.condition('sentDate', '>=', fromDate)
if (thruDate) find = find.condition('sentDate', '<', thruDate)
if (text) find = find.condition(cf.makeCondition('titleText', 'like', '%' + text + '%', false, true))
notificationListCount = find.copy().count()
notificationListPageMaxIndex = Math.max(0, Math.ceil(notificationListCount / notificationListPageSize) - 1)
const rows = Array.from(find.orderBy(orderByField || '-sentDate').orderBy('-notificationMessageId')
        .offset(notificationListPageIndex, notificationListPageSize).limit(notificationListPageSize).list())

const actorNames = new Map()
const actorName = (actorUserId) => {
    if (!actorUserId) return null
    if (!actorNames.has(actorUserId)) {
        const account = ec.entity.find('moqui.security.UserAccount').condition('userId', actorUserId)
                .useCache(true).disableAuthz().one()
        actorNames.set(actorUserId, account ? (account.userFullName || account.username) : null)
    }
    return actorNames.get(actorUserId)
}
for (const row of rows) {
    const topicRow = topics.get(row.topic)
    let message = null
    if (row.messageJson) {
        try {
            message = JSON.parse(row.messageJson)
        } catch (e) {
            ec.logger.warn(`Notification ${row.notificationMessageId} has a messageJson that is not JSON: ${e}`)
        }
    }
    notificationList.push({notificationMessageId: row.notificationMessageId, topic: row.topic,
        topicDescription: topicRow?.description || null, subTopic: row.subTopic, inboxEnumId: inboxOf(row.topic),
        titleText: row.titleText, linkText: row.linkText, typeString: row.typeString, sentDate: row.sentDate,
        userSentDate: row.userSentDate, viewedDate: row.viewedDate, reasonEnumId: row.reasonEnumId,
        recordEntityName: row.recordEntityName, recordId: row.recordId, actorUserId: row.actorUserId,
        actorName: actorName(row.actorUserId), appName: row.appName,
        message: message && typeof message === 'object' && !Array.isArray(message) ? message : null,
        canApprove: !!topicRow?.approveServiceName, canRefuse: !!topicRow?.refuseServiceName,
        refuseReasonRequired: topicRow?.refuseReasonRequired === 'Y'})
}

viewedCount = 0
const userId = ec.user.userId
if (!userId) { ec.message.addError('Notifications are marked viewed only for a signed in user'); return }
let ids = notificationMessageIdList ? Array.from(notificationMessageIdList).filter((id) => id) : []
if (notificationMessageId) ids.push(notificationMessageId)
let find = ec.entity.find('moqui.security.user.NotificationMessageByUser').condition('userId', userId)
        .condition('viewedDate', null).selectField('notificationMessageId').disableAuthz()
if (ids.length) {
    find = find.condition('notificationMessageId', 'in', ids)
} else {
    const topics = Array.from(ec.entity.find('moqui.security.user.NotificationTopic').useCache(true).disableAuthz().list())
    const updateTopics = topics.filter((row) => !row.approveServiceName && row.inboxEnumId === 'NinUpdates').map((row) => row.topic)
    // an approval waiting is decided, not read: all of an inbox leaves it
    const approvalTopics = topics.filter((row) => row.approveServiceName).map((row) => row.topic)
    if (inboxEnumId === 'NinUpdates') {
        if (!updateTopics.length) return
        find = find.condition('topic', 'in', updateTopics)
    } else {
        const left = inboxEnumId ? updateTopics.concat(approvalTopics) : approvalTopics
        if (left.length) {
            const cf = ec.entity.conditionFactory
            find = find.condition(cf.makeCondition([cf.makeCondition('topic', 'not-in', left),
                    cf.makeCondition('topic', 'equals', null)], 'or'))
        }
    }
}
const now = ec.user.nowTimestamp
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    for (const row of Array.from(find.list())) {
        const messageUser = ec.entity.makeValue('moqui.security.user.NotificationMessageUser')
        messageUser.notificationMessageId = row.notificationMessageId
        messageUser.userId = userId
        messageUser.viewedDate = now
        messageUser.update()
        viewedCount++
    }
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

results = null
const userId = ec.user.userId
if (!userId) { ec.message.addError('A decision on a notification needs a signed in user'); return }
const refuse = decision === 'refuse'
const messageUser = ec.entity.find('moqui.security.user.NotificationMessageUser')
        .condition('notificationMessageId', notificationMessageId).condition('userId', userId).disableAuthz().one()
if (!messageUser) { ec.message.addError(`Notification ${notificationMessageId} is not addressed to you`); return }
const message = ec.entity.find('moqui.security.user.NotificationMessage')
        .condition('notificationMessageId', notificationMessageId).disableAuthz().one()
const topic = message?.topic ? ec.entity.find('moqui.security.user.NotificationTopic').condition('topic', message.topic)
        .useCache(true).disableAuthz().one() : null
const serviceName = refuse ? topic?.refuseServiceName : topic?.approveServiceName
if (!serviceName) {
    ec.message.addError(`Notification topic ${message?.topic || ''} has no ${refuse ? 'refuse' : 'approve'} service`)
    return
}
if (refuse && topic.refuseReasonRequired === 'Y' && !(reason && String(reason).trim())) {
    ec.message.addError('A reason is required to refuse this')
    return
}
let parsed = {}
if (message.messageJson) {
    try {
        const json = JSON.parse(message.messageJson)
        if (json && typeof json === 'object' && !Array.isArray(json)) parsed = json
    } catch (e) {
        ec.logger.warn(`Notification ${notificationMessageId} has a messageJson that is not JSON: ${e}`)
    }
}
const parameters = {recordEntityName: message.recordEntityName, recordId: message.recordId, message: parsed,
    notificationMessageId: notificationMessageId}
if (refuse) parameters.reason = reason
try {
    results = ec.service.sync().name(serviceName).parameters(parameters).call()
} catch (e) {
    ec.message.addError(String(e.message || e))
}
if (ec.message.hasError()) return
// the decision is the message's: every recipient's row is marked, so no one else sees it waiting
const now = ec.user.nowTimestamp
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const recipients = ec.entity.find('moqui.security.user.NotificationMessageUser')
            .condition('notificationMessageId', notificationMessageId).condition('viewedDate', null).list()
    for (const recipient of Array.from(recipients)) {
        recipient.viewedDate = now
        recipient.update()
    }
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

userCount = 0
notificationCount = 0
const topics = new Map()
for (const row of Array.from(ec.entity.find('moqui.security.user.NotificationTopic').disableAuthz().list())) topics.set(row.topic, row)
const userRows = Array.from(ec.entity.find('moqui.security.user.NotificationTopicUser').condition('digest', 'Y').disableAuthz().list())
const candidates = new Set(Array.from(topics.values()).filter((row) => row.digestDefault === 'Y').map((row) => row.topic))
for (const row of userRows) candidates.add(row.topic)
if (!candidates.size) return

// each user's choices for the candidate topics, for the digest and the immediate email
const choices = new Map()
for (const row of Array.from(ec.entity.find('moqui.security.user.NotificationTopicUser')
        .condition('topic', 'in', Array.from(candidates)).disableAuthz().list())) choices.set(row.topic + '\u0000' + row.userId, row)
const since = new Date(Date.now() - (hours || 24) * 3600000)
const rows = Array.from(ec.entity.find('moqui.security.user.NotificationMessageByUser')
        .condition('topic', 'in', Array.from(candidates)).condition('viewedDate', null).condition('digestDate', null)
        .condition('emailMessageId', null).condition('sentDate', '>=', since)
        .selectField('notificationMessageId,userId,topic').orderBy('userId,sentDate').disableAuthz().list())
const byUser = new Map()
for (const row of rows) {
    const topic = topics.get(row.topic)
    const choice = choices.get(row.topic + '\u0000' + row.userId)
    const digest = choice?.digest ? choice.digest === 'Y' : topic?.digestDefault === 'Y'
    if (!digest) continue
    // a topic the user gets by email at once was emailed already
    const immediate = choice?.emailNotifications ? choice.emailNotifications === 'Y' : topic?.emailNotifications === 'Y'
    if (immediate && topic?.emailTemplateId) continue
    if (!byUser.has(row.userId)) byUser.set(row.userId, [])
    byUser.get(row.userId).push(row.notificationMessageId)
}

for (const [userId, ids] of byUser) {
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('org.moqui.impl.NotificationServices.send#UserNotificationDigest')
                .parameters({userId: userId, notificationMessageIdList: ids, emailTemplateId: emailTemplateId,
                    ignoreHour: !!ignoreHour})
                .requireNewTransaction(true).call()
        if (ec.message.hasError()) {
            ec.logger.error(`The notification digest of user ${userId} was not sent: ${ec.message.getErrorsString()}`)
        } else if (out?.sentCount) {
            userCount++
            notificationCount += out.sentCount
        }
    } catch (e) {
        ec.logger.error(`The notification digest of user ${userId} was not sent: ${e}`)
    } finally {
        ec.message.popErrors()
    }
}
// the zone and locale the user digests set are for this job's session only
if (byUser.size && !ec.user.userId) { ec.user.setTimeZone(null); ec.user.setLocale(null) }

sentCount = 0
const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).disableAuthz().one()
if (!account?.emailAddress || account.disabled === 'Y') return
// a script sees a time stamp as its epoch millis
if (account.terminateDate && Number(ec.user.nowTimestamp) > Number(account.terminateDate)) return
// not ec.user.internalLoginUser: that refuses an account whose password must be changed
if (!ec.user.userId) {
    ec.user.setTimeZone(account.timeZone || ec.user.machineTimeZone)
    ec.user.setLocale(account.locale || null)
}
// the job is not signed in as this user, so the hour is the preference row, not ec.user.getPreference
if (!ignoreHour) {
    let want = 6
    const pref = ec.entity.find('moqui.security.UserPreference').condition('userId', userId)
            .condition('preferenceKey', 'NOTIFICATION_DIGEST_HOUR').disableAuthz().one()
    const parsed = parseInt(pref && pref.preferenceValue, 10)
    if (parsed >= 0 && parsed <= 23) want = parsed
    const nowHour = parseInt(ec.l10n.format(ec.user.nowTimestamp, 'H'), 10)
    if (nowHour !== want) return
}
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const rows = Array.from(ec.entity.find('moqui.security.user.NotificationMessageByUser').condition('userId', userId)
            .condition('notificationMessageId', 'in', Array.from(notificationMessageIdList)).condition('viewedDate', null)
            .condition('digestDate', null).orderBy('sentDate').list())
    if (!rows.length) return
    const topics = new Map()
    const notificationList = rows.map((row) => {
        if (!topics.has(row.topic)) topics.set(row.topic, ec.entity.find('moqui.security.user.NotificationTopic')
                .condition('topic', row.topic).useCache(true).one())
        return {notificationMessageId: row.notificationMessageId, topic: row.topic,
            topicDescription: topics.get(row.topic)?.description || row.topic, title: row.titleText || '',
            link: row.linkText || '', type: row.typeString || 'info', sentDate: row.sentDate,
            sentText: ec.l10n.format(row.sentDate, 'yyyy-MM-dd HH:mm'), reasonEnumId: row.reasonEnumId,
            appName: row.appName}
    })
    const out = ec.service.sync().name('org.moqui.impl.EmailServices.send#EmailTemplate').parameters({
        emailTemplateId: emailTemplateId, toAddresses: account.emailAddress, toUserId: userId,
        bodyParameters: {notificationList: notificationList, notificationCount: notificationList.length,
            userId: userId, userFullName: account.userFullName || account.username}}).call()
    if (ec.message.hasError()) return
    emailMessageId = out?.emailMessageId || null
    const now = ec.user.nowTimestamp
    for (const row of rows) {
        const messageUser = ec.entity.makeValue('moqui.security.user.NotificationMessageUser')
        messageUser.notificationMessageId = row.notificationMessageId
        messageUser.userId = userId
        messageUser.digestDate = now
        if (emailMessageId) messageUser.emailMessageId = emailMessageId
        messageUser.update()
    }
    sentCount = rows.length
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}
